def car_race_collision(n: int):
    left_to_right = sorted(range(n))
    right_to_left = sorted(range(n))

    collisions = 0
    left_idx = 0
    right_idx = 0

    while left_idx < n and right_idx < n:
        if left_to_right[left_idx] < right_to_left[right_idx]:
            left_idx += 1
        elif left_to_right[left_idx] > right_to_left[right_idx]:
            right_idx += 1
        else:
            collisions += 1
            left_idx += 1
            right_idx += 1

    return collisions

